questionvariables.text:
/* paramètres du montage de diffraction */
a1: rand([20,30,40,50,60,80,100]);  /* largeur fente en µm */
ua: float(round(a1*rand(100)/100))/10         /*incertitude en *m fente commerciales +- 10% */
D1: rand([1,1.5,2,2.5,3]);           /* distance écran en m */
uD:1E-3*(rand(2)+1)/2  /* incertitude sur D en m */

/* Sélection aléatoire du laser */
lasers: [[405,"blue"],[520,"green"],[532,"green"],[635,"red"],[650,"red"]];
laser_choisi: rand(lasers);
lambda: laser_choisi[1];            /* longueur d'onde en nm */
couleur: laser_choisi[2];           /* couleur du laser */
ul:0.06E-3;
l1:float(D1*lambda/a1);


ta1:[[1,false,"C'est de la réfraction"],[2,false,"C'est de la diffusion"],[3,false,"C'est le phénomène d'interférences"],[4,true,"C'est le phénomène de diffraction"]];
feedback1:[["La réfraction est le changement de direction de propagation d'une onde lorsqu'elle passe d'un milieu transparent à un autre (ex: air à eau). L'expérience décrite se fait dans un seul milieu (l'air) et implique le contournement d'un obstacle ou d'une ouverture, ce qui n'est pas la réfraction."],
["La diffusion est la dispersion de la lumière dans toutes les directions par des particules ou des irrégularités du milieu (ex: diffusion Rayleigh par les molécules de l'atmosphère). Bien que la diffraction soit parfois considérée comme un type de diffusion, le terme exact pour l'étalement de l'onde après passage par une fente est la diffraction. La figure observée (maxima/minima réguliers) est caractéristique de la diffraction."],
["La figure observée est le résultat de la superposition des ondes émises par chaque point de la fente. Cependant, l'étalement de l'onde après le passage par une seule fente est le phénomène appelé diffraction. Le terme interférences est réservé à la superposition d'ondes provenant de deux ou plusieurs sources distinctes (comme dans l'expérience des fentes de Young)."],
["La diffraction est le phénomène d'étalement (ou de courbure) des ondes (ici, la lumière laser) lorsqu'elles rencontrent un obstacle ou passent par une petite ouverture (ici, une fente de largeur a). La figure obtenue sur l'écran (alternance de franges lumineuses et sombres avec une frange centrale plus large et intense) est la signature classique de la diffraction par une fente unique."]];
ta2:l/(2*D);
ta3:float(lambda/a1*1E-3); 
ta4:lambda*nm;  
ta5_int: lambda *( (ua/a1)^2 +(uD/D1)^2+ (ul/l1)^2)^0.5;
p: floor(log(abs(ta5_int)) / log(10));
k: 10^( (2-1) - p );  /* 2 est le nombre de CS */
ta5:float((round(ta5_int * k) / k))*nm;
/*calcul des incertitudes*/
para:[[1,false,"une fente de meilleure précision"],[2,false,"une distance D plus précise"],[3,false,"un réticule plus précis"]];
inc_rel_a:ua/a1;
inc_rel_D:uD/D1;
inc_rel_l:ul/l1;

/* 1. Trouver la plus petite valeur */
max_valeur: max(inc_rel_a, inc_rel_D, inc_rel_l);

ta6: [
    [1, is(inc_rel_a = max_valeur), "une fente de meilleure précision (a)"],
    [2, is(inc_rel_D = max_valeur), "une distance D plus précise"],
    [3, is(inc_rel_l = max_valeur), "une mesure l plus précise"]
];
feedback6: block(
        if is(ta6[1][2]) then return("La valeur de l'incertitude relative sur a (largeur de la fente) est la plus élevée, c'est donc le paramètre le plus critique à améliorer.") else

    /* Si la deuxième option (D) est correcte */
    if is(ta6[2][2]) then return("La valeur de l'incertitude relative sur D (distance à l'écran) est la plus élevée, c'est le paramètre à améliorer en priorité.") else

    /* Par défaut (si aucune des deux premières, c'est la troisième, l) */
    return("L'incertitude relative sur l (la largeur de la tache centrale) est la plus grande, donc un réticule plus précis est la meilleure solution.")
);
ta7:float( (lambda+ta5/nm))*nm;
ta8:float((lambda-ta5/nm))*nm;

feedbackvariables.text:
p1: floor(log(abs(ans3)) / log(10));
verif1:ans3/10^p1;
p2: floor(log(abs(ta3)) / log(10));
verif2:ta3/10^p2;

p3: floor(log(abs(ans4)) / log(10));
verif3:ans4/10^p1;
p4: floor(log(abs(ta4)) / log(10));
verif4:ta3/10^p2;
